$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

# ---------------------------------------------------------------
# Aplica los cambios del modulo de Equipos:
#  - oculta la sub-tab "Especificacion tecnica · Revisiones"
#  - permite reutilizar nombres de equipos archivados
#  - marca con "(restaurado)" al restaurar si ya existe otro activo
# Despues regenera caches y recicla el Application Pool.
# ---------------------------------------------------------------

$APP_ROOT  = if ($env:APP_ROOT) { $env:APP_ROOT.TrimEnd('\\', '/') } else { 'C:\inetpub\wwwroot\gestor-archivos' }
$PHP_EXE   = if ($env:PHP_EXE) { $env:PHP_EXE } else { 'C:\php\php.exe' }
$POOL_NAME = if ($env:POOL_NAME) { $env:POOL_NAME } else { 'Gestor de Archivos' }
$appcmd    = Join-Path $env:windir 'System32\inetsrv\appcmd.exe'

if (-not (Test-Path -LiteralPath $APP_ROOT)) { throw "No existe APP_ROOT: $APP_ROOT" }
if (-not (Test-Path -LiteralPath $PHP_EXE)) { throw "No existe PHP: $PHP_EXE" }
if (-not (Test-Path -LiteralPath $appcmd)) { throw "No existe appcmd.exe: $appcmd" }

$payloads = @(
    @{ Relative = 'app\\Filament\\RelationManagers\\TechnicalSpecificationsRelationManager.php'; Base64 = '' }
    @{ Relative = 'app\\Filament\\Resources\\Equipment\\Schemas\\EquipmentForm.php'; Base64 = '' }
    @{ Relative = 'app\\Filament\\Actions\\RestoreAction.php'; Base64 = '' }
    @{ Relative = 'app\\Models\\Equipment.php'; Base64 = '' }
    @{ Relative = 'app\\Console\\Commands\\SyncEquipmentFolder.php'; Base64 = '' }
)

foreach ($item in $payloads) {
    $target = Join-Path $APP_ROOT $item.Relative
    $parent = Split-Path -Parent $target
    if (-not (Test-Path -LiteralPath $parent)) { New-Item -ItemType Directory -Path $parent -Force | Out-Null }
    [IO.File]::WriteAllBytes($target, [Convert]::FromBase64String($item.Base64))
    Write-Host "Actualizado: $target"
}

Set-Location -LiteralPath $APP_ROOT

& $PHP_EXE artisan optimize:clear 2>$null | Out-Null
if ($LASTEXITCODE -ne 0) { throw 'php artisan optimize:clear fallo' }

& $PHP_EXE artisan optimize 2>$null | Out-Null
if ($LASTEXITCODE -ne 0) { throw 'php artisan optimize fallo' }

& $PHP_EXE artisan filament:optimize 2>$null | Out-Null
if ($LASTEXITCODE -ne 0) { throw 'php artisan filament:optimize fallo' }

& $appcmd recycle apppool "/app.pool.name:$POOL_NAME" 2>$null | Out-Null
if ($LASTEXITCODE -ne 0) { Write-Host 'WARN: no se pudo reciclar el pool; reciclalo manualmente.' }

Write-Host 'LISTO. Probar: crear equipo con nombre archivado y restaurar otro con el mismo nombre.'
